urlset:
{% for page in pages %}

    {{ ABSOLUTE_BASE_URL }}/{{ '' if page.slug == HOME_SLUG else page.url }}

{% endfor %}

    {{ ABSOLUTE_BASE_URL }}/{{ INDEX_SAVE_AS }}

{% for article in articles %}

    {{ ABSOLUTE_BASE_URL }}/{{ article.url }}
    {{ (article.modified or article.date).strftime('%Y-%m-%d') }}

{% endfor %}
